INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62163835', 62163835, 'analyze_legacy', 'Provinsi DKI Jakarta', 'provinsi', 'SUKU DINAS KOMUNIKASI, INFORMATIKA DAN STATISTIK KOTA - JAKBAR', 'Tenaga Komunikasi Informasi Publik Fotografer', 'Jasa Lainnya', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Barat (Kota)', 408538000, 'November 2025', 'APBD', 1, 1, '2 Orang x 13 Bulan', 'a. Mendokumentasikan kegiatan Pemerintah Kota Administrasi Jakarta Barat dalam bentuk foto/video. b. Mensortir foto/video kegiatan yang akan digunakan sebagai bahan publikasi di media milik Sudis Kominfotik serta arsip dokumentasi. c. Membuat berita/caption atau memberikan informasi singkat mengenai kegiatan yang telah didokumentasikan. d. Melaksanakan penyimpanan file hasil dokumentasi di tempat penyimpanan yang telah ditentukan. e. Melaksanakan dukungan pengambilan dokumentasi melalui perangkat drone jika diperlukan. f. Menyusun laporan dan dokumentasi pekerjaan. g. Melaksanakan tugas lain yang diperintahkan pimpinan.', 'a. Pendidikan minimal SMA; b. Memiliki pengalaman kerja di bidang fotografi/videografi minimal 1 tahun yang dibuktikan dengan surat keterangan pengalaman kerja; c. Memiliki kemampuan mengambil foto/video dengan baik serta menguasai penggunaan kamera dan kelengkapannya; d. Memahami framing, layouting, penyesuaian warna dan lighting; e. Memiliki kreatifitas yang tinggi serta memahami tren sosial dan digital saat ini; f. Memiliki kemampuan melakukan clean editing post production (coloring, detailing, retouching); g. Memiliki sertifikat keahlian/kompetensi di bidang fotografi/videografi yang dikeluarkan maksimal 2 tahun terakhir; h. Memiliki kemampuan editing video dan kemampuan mengoperasikan drone menjadi nilai tambah; i. Diutamakan memiliki pemahaman yang baik terhadap wilayah Jakarta Barat.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 281075);
