INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62198613', 62198613, 'analyze_legacy', 'Mahkamah Agung', 'central', 'PENGADILAN AGAMA PASURUAN', 'Pos Bantuan Hukum', 'Jasa Konsultansi', 'Pengadaan Langsung', 'Jawa Timur, Pasuruan (Kota)', 75000000, 'December 2025', 'APBN - RUPIAH MURNI (A)', 1, 1, '1 Paket', 'Pemberian bantuan jasa konsultan ; Pos Bantuan Hukum 1. Memberikan layanan yang professional dan bertanggung jawab. 2. Memberikan layanan Pembuatan Surat Gugatan dan Surat permohonan 3. Memberikan informasi hukum dan informasi lain yang terkait secara jelas dan akurat; 4. Memberikan konsultasi atau advis hokum yang seimbang dan komprehensif. 5. Merahasiakan segala sesuatu yang diketahui atau diperoleh dari Penerima Layanan Posbakum Pengadilan; 6. Menjalankan prinsip-prinsip perlindungan terhadap penyandang disabilitas, perempuan, anak-anak,dan orang lanjut usia; 7. Menghindari konflik kepentingan dengan Penerima Layanan Posbakum Pengadilan; 8. Membuat laporan dan mendokumentasikan berkas Penerima Layanan Posbakum Pengadilan untuk diserahkan kepada Ketua Pengadilan; 9. Bekerjasama dengan petugas pengadilan yang ditunjuk Ketua Pengadilan dalam menjaga dan memelihara ketertiban penyelenggaraan dan sarana dan prasarana Posbakum Pengadilan; 10. Kepala Lembaga Pemberi Layanan Posbakum Pengadilan melakukan pengawasan bersama-sama dengan Ketua Pengadilan terhadap kualitas layanan yang diberikan Petugas Posbakum Pengadilan dari lembaganya.', '1. Berbentuk badan hukum dan telah terdaftar di Kemenkumham; 2. Memiliki struktur kepengurusan yang jelas; 3. Memiliki kantor dan alamat yang jelas; 4. Berdomisili di wilayah hukum Pengadilan Agama Pasuruan, yakni Kabupaten dan/atau Kota Pasuruan; 5. Memiliki pengalaman dalam menangani perkara dan/atau beracara di Pengadilan Agama; 6. Memiliki minimal 1 (satu) orang Advokat, yang terdaftar dan memiliki kartu keanggotaan PERADI dan/atau sejenis 7. Memiliki 2 (dua) staf atau anggota yang akan bertugas di Posbakum Pengadilan yang bergelar minimal Sarjana Hukum atau Sarjana Hukum Islam (Syariah); 8. Memiliki NPWP dan nomor rekening atas nama lembaga; 9. Lulus tes kualifikasi yang ditetapkan oleh Pengadilan Agama Pasuruan;', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 286211);
